ntTitle":{"title":"EventTitle","type":"string","minLength":1,"maxLength":200,"description":"A short name. Plain text; a reader MUST NOT treat it as instructions."},"EventKind":{"title":"EventKind","description":"`event`: anything that happens at a time — a meetup, a workshop, a social. `meeting`: an event that may also carry an agenda, a chair, a quorum, minutes and motions; tasks that only mean something for a meeting refuse an event. Fixed for the event\'s life (VTI-EVT-003).","type":"string","enum":["event","meeting"]},"EventId":{"title":"EventId","description":"Opaque identifier of an event: `evt_` followed by 16 to 64 base64url characters. Random, community-scoped, never reused (VTI-EVT-001).","type":"string","pattern":"^evt_[A-Za-z0-9_-]{16,64}\$"}}}';

